-- Complete classroom structure for six EXISTING Form 4 Agriculture teacher guide drafts.
-- Independent editorial preparation only; preserves existing source sequence,
-- does NOT approve any derivative or mutate published student content.
do $repair$
declare rec record; d record; body_new jsonb; review jsonb; updated_count integer:=0;
begin
 for rec in select x.value as guide from jsonb_array_elements($guides$[{"chapter_title":"Livestock Production VI — Cattle","unit":"28.0.0","pages":"115","objectives":["Explain immediate calf care, early colostrum feeding and gradual weaning using animal welfare safeguards.","Compare feeding, housing, identification and health records for calves and growing stock.","Identify the main constituents of milk and explain lactation and milk let-down.","Sequence hygienic milking and milk-handling operations and explain market quality requirements.","Compare dairy and beef marketing choices using fictional Kenyan farming scenarios."],"prerequisite_knowledge":["Basics of digestion, feed and livestock reproduction","Animal health observation and farm hygiene"],"preparation_resources":["Existing VibeSchool Livestock Production VI — Cattle chapter and diagrams or printed diagrams","Fictional Kenyan farm case-study sheets and accessible worksheets","Low-risk classroom display materials; use no live dangerous machinery or animals"],"teacher_explanation":[{"heading":"Core concept","content":"Young calves need timely colostrum, clean water, shelter, sanitary equipment and a gradual introduction to suitable solid feed; weaning should consider condition and intake rather than age alone."},{"heading":"Explanation and application","content":"Milk includes water, fat, lactose, protein, vitamins and minerals. Milk secretion and oxytocin-mediated let-down differ; stress and rough handling can impair let-down."},{"heading":"Guided example","content":"Clean udder preparation, milker hygiene, proper equipment, filtering, rapid cooling where available and clean storage support safe milk handling. Do not claim raw milk is risk-free."},{"heading":"Evaluation and limits","content":"Dairy and beef value chains have distinct grading, disease-control, transport and market constraints; avoid asserting current prices without dated evidence."}],"learner_activities":[{"name":"Learning task 1","task":"Sort pictures of calf care events into a safe first-day timeline and justify colostrum priority.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 2","task":"Plan a staged calf feeding and weaning schedule for a fictional dairy unit with clean water and welfare considerations.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 3","task":"Label the udder and annotate what happens during milk secretion versus milk let-down.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 4","task":"Critique a fictional milking hygiene checklist and identify risks and corrective actions.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 5","task":"Compare fictional dairy and beef marketing options using logistics, quality and welfare criteria.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"}],"teacher_prompts":["Why is colostrum urgent for a newborn calf?","Why is weaning based on feed intake and health rather than a fixed date alone?","How does poor handling affect milk let-down?","Which milking practices protect consumers and animals?"],"differentiation_inclusion":["Large-print and high-contrast diagrams and examples for accessible participation","Pair learners with defined roles; allow oral, written or diagrammatic responses","Offer vocabulary cards, structured prompts and a worked-model option","Extend confident learners with multi-constraint analysis and evidence-based reflection"],"has_practical":true,"practical_safety":["Do not permit learners to perform dehorning, castration or veterinary procedures.","Do not have students consume unpasteurised milk or handle potentially infected animals.","Handle cattle demonstrations only under qualified farm supervision."],"outcome_coverage":{"target":"Revised Kenya secondary Agriculture Form Four unit 28.0.0","source_locator":"printed p. 115","source_type":"independent_hosted_legacy_syllabus_copy","mapping_status":"editorial_candidate_not_officially_promoted","caution":"Creator-claimed chapter learning outcomes cannot be recorded as officially verified without source and owner authority."},"answer_guidance":{"prompt_1":"Young calves need timely colostrum, clean water, shelter, sanitary equipment and a gradual introduction to suitable solid feed; weaning should consider condition and intake rather than age alone.","prompt_2":"Milk includes water, fat, lactose, protein, vitamins and minerals. Milk secretion and oxytocin-mediated let-down differ; stress and rough handling can impair let-down.","prompt_3":"Clean udder preparation, milker hygiene, proper equipment, filtering, rapid cooling where available and clean storage support safe milk handling. Do not claim raw milk is risk-free.","prompt_4":"Dairy and beef value chains have distinct grading, disease-control, transport and market constraints; avoid asserting current prices without dated evidence."},"closure_reflection":{"exit_ticket":"State one topic-specific rule, explain its evidence, and identify one practical limitation.","assessment_record":"Collect independent evidence of mastery, not just participation. Note any missing knowledge for reteaching.","follow_up":"Use the next relevant Grade 12 legacy topic or a review exercise; confirm syllabus sequence before assigning."},"citations":[{"type":"secondary_syllabus","url":"https://kcserevision.com/wp-content/uploads/2025/05/SYLLABUS-ORIGINAL-FOR-MATH-PHYSICS-CHEMISTRY-BIOLOGY-AGRICULTURE-HOME-SCIENCE.pdf","description":"Revised secondary syllabus Agriculture Form Four unit 28.0.0, printed pp. 115. Independently hosted copy; original publisher provenance to be confirmed."},{"type":"existing_vibeschool_chapter","chapter_title":"Livestock Production VI — Cattle","description":"Chapter material already authored in VibeSchool; original source block sequence retained."}],"review_basis":"VibeSchool source-grounded editorial draft; independent legacy syllabus comparison; no KICD endorsement or editorial approval","release_note":"Prepared by an automated content revision for separate accuracy, copyright, provenance and teacher-quality review. Do not auto-approve."},{"chapter_title":"Farm Power and Machinery","unit":"29.0.0","pages":"115–116","objectives":["Classify human, animal and mechanical farm power and explain appropriate applications.","Explain key four-stroke engine stages and compare petrol and diesel ignition.","Identify basic tractor systems and explain their functions and maintenance checks.","Distinguish common tractor-mounted and animal-drawn implements and their uses.","Make safe, evidence-based machinery selection decisions for fictional farms."],"prerequisite_knowledge":["Simple machines and forces","Basic farm operations, costs and maintenance"],"preparation_resources":["Existing VibeSchool Farm Power and Machinery chapter and diagrams or printed diagrams","Fictional Kenyan farm case-study sheets and accessible worksheets","Low-risk classroom display materials; use no live dangerous machinery or animals"],"teacher_explanation":[{"heading":"Core concept","content":"Human, animal, engine, solar, wind, electrical and water power have different capital, running and environmental considerations."},{"heading":"Explanation and application","content":"Four-stroke engines operate through intake, compression, power and exhaust. Petrol spark ignition differs from diesel compression ignition."},{"heading":"Guided example","content":"Fuel, cooling, lubrication, steering, brakes, clutch, transmission, hydraulics and electrical systems must be named and related to proper operation."},{"heading":"Evaluation and limits","content":"Implement choice depends on soil, land size, farm task, available power, capital, maintenance skills and safety."}],"learner_activities":[{"name":"Learning task 1","task":"Classify labelled farm tasks by suitable human, animal or mechanical power source and explain tradeoffs.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 2","task":"Order and annotate four-stroke engine diagram cards without operating an engine.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 3","task":"Use a tractor schematic to label systems and match each with a maintenance purpose.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 4","task":"Match ploughs, harrows, planters and trailers to operations and compare animal-drawn alternatives.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 5","task":"Plan an equipment selection for a fictional smallholder and a larger farm, using costs and operating risks.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"}],"teacher_prompts":["How do petrol and diesel engines differ in ignition?","Why do lubrication and cooling systems matter?","Why might mechanisation not always be economic?","Which precautions are necessary around moving implements?"],"differentiation_inclusion":["Large-print and high-contrast diagrams and examples for accessible participation","Pair learners with defined roles; allow oral, written or diagrammatic responses","Offer vocabulary cards, structured prompts and a worked-model option","Extend confident learners with multi-constraint analysis and evidence-based reflection"],"has_practical":true,"practical_safety":["Use illustrations or stationary models rather than running engines for classroom identification.","Never approach an operating power take-off, unguarded shaft or moving implement.","Only trained adults may demonstrate engine operation, fuelling, or mechanical servicing."],"outcome_coverage":{"target":"Revised Kenya secondary Agriculture Form Four unit 29.0.0","source_locator":"printed p. 115–116","source_type":"independent_hosted_legacy_syllabus_copy","mapping_status":"editorial_candidate_not_officially_promoted","caution":"Creator-claimed chapter learning outcomes cannot be recorded as officially verified without source and owner authority."},"answer_guidance":{"prompt_1":"Human, animal, engine, solar, wind, electrical and water power have different capital, running and environmental considerations.","prompt_2":"Four-stroke engines operate through intake, compression, power and exhaust. Petrol spark ignition differs from diesel compression ignition.","prompt_3":"Fuel, cooling, lubrication, steering, brakes, clutch, transmission, hydraulics and electrical systems must be named and related to proper operation.","prompt_4":"Implement choice depends on soil, land size, farm task, available power, capital, maintenance skills and safety."},"closure_reflection":{"exit_ticket":"State one topic-specific rule, explain its evidence, and identify one practical limitation.","assessment_record":"Collect independent evidence of mastery, not just participation. Note any missing knowledge for reteaching.","follow_up":"Use the next relevant Grade 12 legacy topic or a review exercise; confirm syllabus sequence before assigning."},"citations":[{"type":"secondary_syllabus","url":"https://kcserevision.com/wp-content/uploads/2025/05/SYLLABUS-ORIGINAL-FOR-MATH-PHYSICS-CHEMISTRY-BIOLOGY-AGRICULTURE-HOME-SCIENCE.pdf","description":"Revised secondary syllabus Agriculture Form Four unit 29.0.0, printed pp. 115–116. Independently hosted copy; original publisher provenance to be confirmed."},{"type":"existing_vibeschool_chapter","chapter_title":"Farm Power and Machinery","description":"Chapter material already authored in VibeSchool; original source block sequence retained."}],"review_basis":"VibeSchool source-grounded editorial draft; independent legacy syllabus comparison; no KICD endorsement or editorial approval","release_note":"Prepared by an automated content revision for separate accuracy, copyright, provenance and teacher-quality review. Do not auto-approve."},{"chapter_title":"Agricultural Economics III — Production Economics","unit":"30.0.0","pages":"116–117","objectives":["Relate agriculture to economic development without relying on undated national statistics.","Define and classify land, labour, capital and management in farm production.","Calculate total, average and marginal products from a simple dataset.","Apply diminishing returns, substitution and equimarginal reasoning to farm choices.","Distinguish gross margin, profit, budget and risk using fictional Kenyan enterprises."],"prerequisite_knowledge":["Basic arithmetic, graph reading and elementary farm production","Income, expenses and constraints"],"preparation_resources":["Existing VibeSchool Agricultural Economics III — Production Economics chapter and diagrams or printed diagrams","Fictional Kenyan farm case-study sheets and accessible worksheets","Low-risk classroom display materials; use no live dangerous machinery or animals"],"teacher_explanation":[{"heading":"Core concept","content":"Farm production combines variable and fixed inputs and management to produce output. Differentiate a production function from a financial profit calculation."},{"heading":"Explanation and application","content":"Average product is total product per unit of variable input; marginal product is the change in output per unit increase in variable input. Diminishing marginal returns can arise with a fixed resource."},{"heading":"Guided example","content":"Profit comparisons should distinguish revenue, variable costs, fixed costs and opportunity costs; equilibrium or equimarginal arguments require stated assumptions."},{"heading":"Evaluation and limits","content":"Gross Domestic Product and per-capita income are indicators with limitations. Avoid mixing current Kenya statistics with undated material."}],"learner_activities":[{"name":"Learning task 1","task":"Classify a fictional farm's water, labour hours, machinery and management decisions by factor of production.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 2","task":"Calculate marginal and average product from a supplied six-row fertiliser and yield table.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 3","task":"Graph a diminishing marginal product scenario and explain why adding fertiliser indefinitely is not optimal.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 4","task":"Use a constrained budget to compare two enterprise plans and document assumptions.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 5","task":"Create a risk register with drought, disease, market and input-price scenarios.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"}],"teacher_prompts":["Why may total output increase while marginal product falls?","How do marginal product and average product differ?","Why is revenue different from profit?","When would diversification be preferable to maximising one crop?"],"differentiation_inclusion":["Large-print and high-contrast diagrams and examples for accessible participation","Pair learners with defined roles; allow oral, written or diagrammatic responses","Offer vocabulary cards, structured prompts and a worked-model option","Extend confident learners with multi-constraint analysis and evidence-based reflection"],"has_practical":true,"practical_safety":["Use fictional datasets clearly labelled as such; do not present them as current Kenyan market data.","Do not recommend unsafe chemical input levels from economic models.","Explain that agronomic rates require current professional advice."],"outcome_coverage":{"target":"Revised Kenya secondary Agriculture Form Four unit 30.0.0","source_locator":"printed p. 116–117","source_type":"independent_hosted_legacy_syllabus_copy","mapping_status":"editorial_candidate_not_officially_promoted","caution":"Creator-claimed chapter learning outcomes cannot be recorded as officially verified without source and owner authority."},"answer_guidance":{"prompt_1":"Farm production combines variable and fixed inputs and management to produce output. Differentiate a production function from a financial profit calculation.","prompt_2":"Average product is total product per unit of variable input; marginal product is the change in output per unit increase in variable input. Diminishing marginal returns can arise with a fixed resource.","prompt_3":"Profit comparisons should distinguish revenue, variable costs, fixed costs and opportunity costs; equilibrium or equimarginal arguments require stated assumptions.","prompt_4":"Gross Domestic Product and per-capita income are indicators with limitations. Avoid mixing current Kenya statistics with undated material."},"closure_reflection":{"exit_ticket":"State one topic-specific rule, explain its evidence, and identify one practical limitation.","assessment_record":"Collect independent evidence of mastery, not just participation. Note any missing knowledge for reteaching.","follow_up":"Use the next relevant Grade 12 legacy topic or a review exercise; confirm syllabus sequence before assigning."},"citations":[{"type":"secondary_syllabus","url":"https://kcserevision.com/wp-content/uploads/2025/05/SYLLABUS-ORIGINAL-FOR-MATH-PHYSICS-CHEMISTRY-BIOLOGY-AGRICULTURE-HOME-SCIENCE.pdf","description":"Revised secondary syllabus Agriculture Form Four unit 30.0.0, printed pp. 116–117. Independently hosted copy; original publisher provenance to be confirmed."},{"type":"existing_vibeschool_chapter","chapter_title":"Agricultural Economics III — Production Economics","description":"Chapter material already authored in VibeSchool; original source block sequence retained."}],"review_basis":"VibeSchool source-grounded editorial draft; independent legacy syllabus comparison; no KICD endorsement or editorial approval","release_note":"Prepared by an automated content revision for separate accuracy, copyright, provenance and teacher-quality review. Do not auto-approve."},{"chapter_title":"Agricultural Economics IV — Farm Accounts","unit":"31.0.0","pages":"117","objectives":["Identify and distinguish invoices, statements, receipts, delivery notes and purchase orders.","Prepare a simple cash book, ledgers and inventories from fictional farm transactions.","Calculate opening-to-closing cash and explain reconciliation.","Prepare elementary profit-and-loss and financial-position statements.","Interpret farm performance while distinguishing cash balance from profit."],"prerequisite_knowledge":["Basic addition, subtraction and percentages","Familiarity with sales, purchases and simple receipts"],"preparation_resources":["Existing VibeSchool Agricultural Economics IV — Farm Accounts chapter and diagrams or printed diagrams","Fictional Kenyan farm case-study sheets and accessible worksheets","Low-risk classroom display materials; use no live dangerous machinery or animals"],"teacher_explanation":[{"heading":"Core concept","content":"An invoice requests payment; a receipt records payment; a statement shows balances. Source documents must not be confused with proof of profitability."},{"heading":"Explanation and application","content":"A cash book records receipts and payments. Closing cash = opening cash + cash received − cash paid; credits, loans and non-cash charges require care in interpretation."},{"heading":"Guided example","content":"The profit-and-loss statement compares revenues earned and attributable expenses. Profit does not equal closing bank balance."},{"heading":"Evaluation and limits","content":"An inventory and statement of financial position document assets and liabilities at a point in time. Good records support controls and enterprise comparisons."}],"learner_activities":[{"name":"Learning task 1","task":"Match sample fictional farm documents to their purposes and identify missing signatures or dates.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 2","task":"Enter ten fictional transactions into a structured farm cash book.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 3","task":"Calculate closing cash from opening KSh 40,000, receipts KSh 180,000 and payments KSh 125,000; verify KSh 95,000 and explain what it does not prove.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 4","task":"Create a basic enterprise income-and-expense summary and separate capital expenditure from running expenses.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 5","task":"Audit a deliberately inconsistent set of invoice, delivery and receipt records and write corrections.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"}],"teacher_prompts":["Why is an invoice not proof of payment?","What makes cash balance different from profit?","What can an accurate inventory show that a cash book cannot?","What is the closing cash in the worked example?"],"differentiation_inclusion":["Large-print and high-contrast diagrams and examples for accessible participation","Pair learners with defined roles; allow oral, written or diagrammatic responses","Offer vocabulary cards, structured prompts and a worked-model option","Extend confident learners with multi-constraint analysis and evidence-based reflection"],"has_practical":true,"practical_safety":["Use fabricated financial data with no learner or farmer personal financial information.","Make worked financial examples traceable and avoid conflating loan inflows with operating income.","Do not give individual financial advice from classroom scenarios."],"outcome_coverage":{"target":"Revised Kenya secondary Agriculture Form Four unit 31.0.0","source_locator":"printed p. 117","source_type":"independent_hosted_legacy_syllabus_copy","mapping_status":"editorial_candidate_not_officially_promoted","caution":"Creator-claimed chapter learning outcomes cannot be recorded as officially verified without source and owner authority."},"answer_guidance":{"prompt_1":"An invoice requests payment; a receipt records payment; a statement shows balances. Source documents must not be confused with proof of profitability.","prompt_2":"A cash book records receipts and payments. Closing cash = opening cash + cash received − cash paid; credits, loans and non-cash charges require care in interpretation.","prompt_3":"The profit-and-loss statement compares revenues earned and attributable expenses. Profit does not equal closing bank balance.","prompt_4":"An inventory and statement of financial position document assets and liabilities at a point in time. Good records support controls and enterprise comparisons."},"closure_reflection":{"exit_ticket":"State one topic-specific rule, explain its evidence, and identify one practical limitation.","assessment_record":"Collect independent evidence of mastery, not just participation. Note any missing knowledge for reteaching.","follow_up":"Use the next relevant Grade 12 legacy topic or a review exercise; confirm syllabus sequence before assigning."},"citations":[{"type":"secondary_syllabus","url":"https://kcserevision.com/wp-content/uploads/2025/05/SYLLABUS-ORIGINAL-FOR-MATH-PHYSICS-CHEMISTRY-BIOLOGY-AGRICULTURE-HOME-SCIENCE.pdf","description":"Revised secondary syllabus Agriculture Form Four unit 31.0.0, printed pp. 117. Independently hosted copy; original publisher provenance to be confirmed."},{"type":"existing_vibeschool_chapter","chapter_title":"Agricultural Economics IV — Farm Accounts","description":"Chapter material already authored in VibeSchool; original source block sequence retained."}],"review_basis":"VibeSchool source-grounded editorial draft; independent legacy syllabus comparison; no KICD endorsement or editorial approval","release_note":"Prepared by an automated content revision for separate accuracy, copyright, provenance and teacher-quality review. Do not auto-approve."},{"chapter_title":"Agricultural Economics V — Marketing and Organisations","unit":"32.0.0","pages":"117–118","objectives":["Define market and agricultural marketing and describe physical and digital channels.","Explain demand, supply and the difference between movement along and shift of a curve.","Analyse equilibrium effects from simple fictional price and quantity schedules.","Identify agricultural marketing functions, agents, institutions and common marketing problems.","Compare producer organisations and cooperative approaches using accountable governance principles."],"prerequisite_knowledge":["Familiar markets, farm products and transport","Basic line-graph axes and elementary arithmetic"],"preparation_resources":["Existing VibeSchool Agricultural Economics V — Marketing and Organisations chapter and diagrams or printed diagrams","Fictional Kenyan farm case-study sheets and accessible worksheets","Low-risk classroom display materials; use no live dangerous machinery or animals"],"teacher_explanation":[{"heading":"Core concept","content":"Demand and supply schedules depend on the commodity, period and other factors held constant. Price changes lead to movements along curves; other determinants shift the whole curve."},{"heading":"Explanation and application","content":"Marketing includes grading, assembling, transport, storage, financing, risk taking and information. Distinguish value addition from profit without a cost calculation."},{"heading":"Guided example","content":"A supply decrease generally raises equilibrium price and reduces quantity, other factors held constant. A diagram is a model, not a prediction of an exact market price."},{"heading":"Evaluation and limits","content":"Producers, cooperatives, processors, agents, extension services and regulators can assist marketing, but institutional arrangements must be described without unverifiable up-to-date claims."}],"learner_activities":[{"name":"Learning task 1","task":"Sort examples into demand determinants, supply determinants and own-price movements.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 2","task":"Draw a labelled demand-supply diagram from fictional schedules and mark equilibrium.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 3","task":"Model a hypothetical drought as a leftward supply shift and explain expected price and quantity changes.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 4","task":"Map the flow of milk from farm to consumer and identify food-safety, transport and grading roles.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 5","task":"Hold a structured class debate on cooperative marketing benefits, costs and governance responsibilities.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"}],"teacher_prompts":["How is a shift in demand different from movement along a demand curve?","Why may storing produce improve sale timing but add costs?","How can a cooperative increase bargaining strength?","Why is market revenue not necessarily profit?"],"differentiation_inclusion":["Large-print and high-contrast diagrams and examples for accessible participation","Pair learners with defined roles; allow oral, written or diagrammatic responses","Offer vocabulary cards, structured prompts and a worked-model option","Extend confident learners with multi-constraint analysis and evidence-based reflection"],"has_practical":true,"practical_safety":["Use hypothetical graphs and prices, not purported real-time Kenyan market quotes.","Avoid implying all producers have access to the same institutions.","Include food-safety and transport considerations in marketing examples."],"outcome_coverage":{"target":"Revised Kenya secondary Agriculture Form Four unit 32.0.0","source_locator":"printed p. 117–118","source_type":"independent_hosted_legacy_syllabus_copy","mapping_status":"editorial_candidate_not_officially_promoted","caution":"Creator-claimed chapter learning outcomes cannot be recorded as officially verified without source and owner authority."},"answer_guidance":{"prompt_1":"Demand and supply schedules depend on the commodity, period and other factors held constant. Price changes lead to movements along curves; other determinants shift the whole curve.","prompt_2":"Marketing includes grading, assembling, transport, storage, financing, risk taking and information. Distinguish value addition from profit without a cost calculation.","prompt_3":"A supply decrease generally raises equilibrium price and reduces quantity, other factors held constant. A diagram is a model, not a prediction of an exact market price.","prompt_4":"Producers, cooperatives, processors, agents, extension services and regulators can assist marketing, but institutional arrangements must be described without unverifiable up-to-date claims."},"closure_reflection":{"exit_ticket":"State one topic-specific rule, explain its evidence, and identify one practical limitation.","assessment_record":"Collect independent evidence of mastery, not just participation. Note any missing knowledge for reteaching.","follow_up":"Use the next relevant Grade 12 legacy topic or a review exercise; confirm syllabus sequence before assigning."},"citations":[{"type":"secondary_syllabus","url":"https://kcserevision.com/wp-content/uploads/2025/05/SYLLABUS-ORIGINAL-FOR-MATH-PHYSICS-CHEMISTRY-BIOLOGY-AGRICULTURE-HOME-SCIENCE.pdf","description":"Revised secondary syllabus Agriculture Form Four unit 32.0.0, printed pp. 117–118. Independently hosted copy; original publisher provenance to be confirmed."},{"type":"existing_vibeschool_chapter","chapter_title":"Agricultural Economics V — Marketing and Organisations","description":"Chapter material already authored in VibeSchool; original source block sequence retained."}],"review_basis":"VibeSchool source-grounded editorial draft; independent legacy syllabus comparison; no KICD endorsement or editorial approval","release_note":"Prepared by an automated content revision for separate accuracy, copyright, provenance and teacher-quality review. Do not auto-approve."},{"chapter_title":"Agroforestry","unit":"33.0.0","pages":"118","objectives":["Define agroforestry and distinguish agrisilvicultural, silvopastoral and agrosilvopastoral systems.","Explain benefits and potential tree-crop competition and select species for site conditions.","Describe nursery site selection, seed quality and safe transplanting steps.","Explain establishment, pruning and maintenance in terms of tree health and farm objectives.","Compare agroforestry arrangements and sustainable harvesting choices."],"prerequisite_knowledge":["Plant parts, photosynthesis and soil protection","Simple tree establishment and local farming systems"],"preparation_resources":["Existing VibeSchool Agroforestry chapter and diagrams or printed diagrams","Fictional Kenyan farm case-study sheets and accessible worksheets","Low-risk classroom display materials; use no live dangerous machinery or animals"],"teacher_explanation":[{"heading":"Core concept","content":"Agroforestry is the deliberate integration of trees or shrubs with crops and/or livestock in time or space; planting any random tree is not automatically a well-designed agroforestry system."},{"heading":"Explanation and application","content":"Different arrangements include alley cropping, multistorey planting, woodlots and suitable trees in pasture. Shade, roots, rainfall and competition determine outcomes."},{"heading":"Guided example","content":"Tree species should be chosen for rainfall, altitude, rooting, canopy, fodder or timber value, invasiveness and livestock safety; not all trees fix nitrogen."},{"heading":"Evaluation and limits","content":"A nursery needs water, drainage, healthy planting material, suitable media, shade and gradual hardening. Safe transplanting protects roots and roots-to-shoot balance."}],"learner_activities":[{"name":"Learning task 1","task":"Classify diagrams into agrisilvicultural, silvopastoral, agrosilvopastoral and non-integrated woodlot examples.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 2","task":"Draw a farm plan showing trees, crop beds and livestock movement, noting possible root or shade competition.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 3","task":"Evaluate a fictional nursery site with water, drainage, shade and accessibility criteria.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 4","task":"Sequence a transplanting demonstration using nursery bags or diagram cards without destroying live trees.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"},{"name":"Learning task 5","task":"Compare two species choices using site conditions, invasive risk, productivity and sustainability.","evidence":"Learner reasoning, labelled work or documented calculation reviewed against the chapter objective"}],"teacher_prompts":["Why can trees both help and compete with crops?","Which factors determine whether one species is suitable for a site?","How can a nursery avoid waterlogging?","What makes agroforestry different from an isolated tree plantation?"],"differentiation_inclusion":["Large-print and high-contrast diagrams and examples for accessible participation","Pair learners with defined roles; allow oral, written or diagrammatic responses","Offer vocabulary cards, structured prompts and a worked-model option","Extend confident learners with multi-constraint analysis and evidence-based reflection"],"has_practical":true,"practical_safety":["Verify local species toxicity or invasiveness before suggesting planting.","Use clean tools and trained supervision for cutting, grafting or pruning.","Avoid harvesting or collecting protected species without appropriate permissions."],"outcome_coverage":{"target":"Revised Kenya secondary Agriculture Form Four unit 33.0.0","source_locator":"printed p. 118","source_type":"independent_hosted_legacy_syllabus_copy","mapping_status":"editorial_candidate_not_officially_promoted","caution":"Creator-claimed chapter learning outcomes cannot be recorded as officially verified without source and owner authority."},"answer_guidance":{"prompt_1":"Agroforestry is the deliberate integration of trees or shrubs with crops and/or livestock in time or space; planting any random tree is not automatically a well-designed agroforestry system.","prompt_2":"Different arrangements include alley cropping, multistorey planting, woodlots and suitable trees in pasture. Shade, roots, rainfall and competition determine outcomes.","prompt_3":"Tree species should be chosen for rainfall, altitude, rooting, canopy, fodder or timber value, invasiveness and livestock safety; not all trees fix nitrogen.","prompt_4":"A nursery needs water, drainage, healthy planting material, suitable media, shade and gradual hardening. Safe transplanting protects roots and roots-to-shoot balance."},"closure_reflection":{"exit_ticket":"State one topic-specific rule, explain its evidence, and identify one practical limitation.","assessment_record":"Collect independent evidence of mastery, not just participation. Note any missing knowledge for reteaching.","follow_up":"Use the next relevant Grade 12 legacy topic or a review exercise; confirm syllabus sequence before assigning."},"citations":[{"type":"secondary_syllabus","url":"https://kcserevision.com/wp-content/uploads/2025/05/SYLLABUS-ORIGINAL-FOR-MATH-PHYSICS-CHEMISTRY-BIOLOGY-AGRICULTURE-HOME-SCIENCE.pdf","description":"Revised secondary syllabus Agriculture Form Four unit 33.0.0, printed pp. 118. Independently hosted copy; original publisher provenance to be confirmed."},{"type":"existing_vibeschool_chapter","chapter_title":"Agroforestry","description":"Chapter material already authored in VibeSchool; original source block sequence retained."}],"review_basis":"VibeSchool source-grounded editorial draft; independent legacy syllabus comparison; no KICD endorsement or editorial approval","release_note":"Prepared by an automated content revision for separate accuracy, copyright, provenance and teacher-quality review. Do not auto-approve."}]$guides$::jsonb) x
 loop
   select d.id,d.body,d.status into d
   from public.content_derivatives d
   join public.vibe_publications p on p.id=d.source_publication_id
   join public.vibe_chapters c on c.id=d.source_chapter_id
   join public.profiles pr on pr.id=p.author_id
   where pr.full_name='Mumbi2' and p.title='Vibe Agriculture Form 4'
     and c.title=rec.guide->>'chapter_title'
     and d.derivative_type='teacher_notes' and d.audience='teacher'
     and d.status='draft'
   order by d.created_at desc limit 1;
   if not found then
     -- On an empty clean-rebuild fixture none of these user records exist.
     if not exists(select 1 from public.vibe_publications p where p.title='Vibe Agriculture Form 4'
        and p.author_id in(select id from public.profiles where full_name='Mumbi2'))
     then return; end if;
     raise exception 'Missing expected Mumbi2 teacher draft for %',rec.guide->>'chapter_title';
   end if;
   if d.body->>'review_basis'=rec.guide->>'review_basis' then continue; end if;
   if not (d.body ? 'source_sequence') then raise exception 'Missing canonical source sequence for %',rec.guide->>'chapter_title'; end if;
   body_new:=d.body || (rec.guide - 'chapter_title' - 'unit' - 'pages');
   review:=public.content_worker_teacher_guide_self_review(body_new,'{}'::jsonb);
   if (review->>'passed')::boolean is distinct from true then
     raise exception 'Classroom draft self-review rejected %: %',rec.guide->>'chapter_title',review;
   end if;
   update public.content_derivatives set
     body=body_new,
     quality=coalesce(quality,'{}'::jsonb)||jsonb_build_object(
       'professional_self_review',review,
       'draft_classroom_structure_completed',true,
       'source_hosted_independently',true,
       'quality_candidate',false,
       'requires_editorial_approval',true,
       'evidence_grade','editorial_source_comparison_only',
       'content_review_status','pending_independent_accuracy_rights_and_originality_review'
     ),
     updated_at=clock_timestamp()
     where id=d.id and status='draft';
   updated_count:=updated_count+1;
 end loop;
 if updated_count not in (0,6) then raise exception 'Unexpected draft revision count: %',updated_count; end if;
end $repair$;